  "outcome": "deny",
  "rationale": "We recommend denying this claim because the automated findings and the claimant's account confirm that the vehicle was being used for a commercial rideshare trip at the time of the collision. This situation is explicitly excluded under the policy terms. Therefore, the loss is not covered.",
  "citations": [
    {
      "clause_id": "PLUS-4.4",
      "quote": "We do not cover loss that occurs while the covered vehicle is being used to carry persons or property for a fee, including rideshare, taxi, courier and paid delivery services"
    }
  ]
}
